miniLab.verifyScript:
param(
    [string]$EchoDir = (Join-Path (Get-Location) 'u0-echo-agent')
)
$ErrorActionPreference = 'Stop'
$fails = 0
$passes = 0
function Check {
    param([string]$Name, [bool]$Ok, [string]$Detail)
    if ($Ok) {
        Write-Host ('[PASS]  ' + $Name)
        $script:passes++
    } else {
        Write-Host ('[FAIL]  ' + $Name + ' - ' + $Detail)
        $script:fails++
    }
}
$projOk = (Test-Path $EchoDir) -and (Test-Path (Join-Path $EchoDir 'Cargo.toml'))
Check 'u0-echo-agent project exists' $projOk 'run cargo new u0-echo-agent in this folder first'
$depsOk = $false
if ($projOk) {
    $cargo = Get-Content (Join-Path $EchoDir 'Cargo.toml') -Raw
    $depsOk = [bool](($cargo -match 'tokio') -and ($cargo -match 'anyhow') -and ($cargo -match 'serde') -and ($cargo -match 'futures') -and ($cargo -match 'async-trait'))
}
Check 'Cargo.toml declares tokio anyhow serde futures async-trait' $depsOk 'run the cargo add commands from the instructions'
$mainPath = Join-Path $EchoDir 'src/main.rs'
if (Test-Path $mainPath) {
    $src = Get-Content $mainPath -Raw
    $c1 = [bool]($src -match 'struct EchoAgent')
    $c2 = [bool](($src -match 'Serialize') -and ($src -match 'Deserialize'))
    $c3 = [bool]($src -match 'for EchoAgent')
    $c4 = [bool]($src -match 'anyhow::Result')
    $c5 = [bool]($src -match 'async fn stream')
    $c6 = [bool]($src -match 'Arc<Mutex<')
    $c7 = [bool](($src -match 'stream::unfold') -and ($src -match 'Box::pin'))
    $c8 = [bool](($src -match 'tokio::join!') -and ($src -match 'ECHO-AGENT-OK'))
    Check 'EchoAgent struct present' $c1 'define struct EchoAgent with a serde config field'
    Check 'serde derive on config struct' $c2 'add #[derive(Serialize, Deserialize)] to EchoConfig'
    Check 'trait implemented for EchoAgent' $c3 'write a trait and impl it for EchoAgent'
    Check 'anyhow::Result in signatures' $c4 'use anyhow::Result in fn signatures'
    Check 'async fn stream present' $c5 'implement an async fn stream method'
    Check 'lock-guarded shared state' $c6 'add Arc<Mutex<HashMap<String, usize>>> as a call log'
    Check 'stream built and pinned' $c7 'yield chunks via futures::stream::unfold and Box::pin'
    Check 'concurrent runs and ECHO-AGENT-OK marker' $c8 'run two streams via tokio::join! and print ECHO-AGENT-OK'
} else {
    Check 'src/main.rs exists' $false 'missing u0-echo-agent/src/main.rs'
}
Write-Host ''
if ($fails -eq 0) {
    Write-Host ('VERIFY PASSED ' + $passes + '/' + ($passes + $fails))
    exit 0
} else {
    Write-Host ('VERIFY FAILED - ' + $fails + ' of ' + ($passes + $fails) + ' checks failed')
    exit 1
}
